-- Fiche This, that, these, those (CM1) - anglais, notion 'en_demonstratifs'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'cm1', 'english', 'This, that, these, those', $fiche$
[titre]Ce, cette, ces[/titre]
